import sys
from math import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

def matrix_mul(A, B, mod):
    size = len(A)
    C = [[0] * size for _ in range(size)]
    for i in range(size):
        for k in range(size):
            if A[i][k] == 0:
                continue
            for j in range(size):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
    return C

def matrix_pow(A, p, mod):
    size = len(A)
    res = [[0] * size for _ in range(size)]
    for r in range(size):
        res[r][r] = 1
    while p > 0:
        if p & 1:
            res = matrix_mul(res, A, mod)
        A = matrix_mul(A, A, mod)
        p >>= 1
    return res

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    n = int(data[idx]); idx += 1
    c = int(data[idx]); idx += 1

    MOD = 12345

    if n == 0:
        print(0 % MOD)
        return

    crime_mods = {}

    for _ in range(c):
        t = data[idx]; idx += 1
        m = int(data[idx]); idx += 1
        if t not in crime_mods:
            crime_mods[t] = []
        crime_mods[t].append(m)

    L = 1
    for mods in crime_mods.values():
        l = 1
        for m in mods:
            l = lcm(l, m)
        L = lcm(L, l)

    if L == 1:
        total = 0
        for mods in crime_mods.values():
            total += 1
        if total == 0:
            print(0)
        else:
            print(pow(total, n, MOD))
        return

    states = list(range(L))
    state_idx = {v: i for i, v in enumerate(states)}
    size = L

    mat = [[0] * size for _ in range(size)]

    for t, mods in crime_mods.items():
        count_t = 0
        for m in mods:
            if m == 1:
                count_t += 1
                break
        else:
            pass

        for s in states:
            next_s = (s + 1) % L
            valid = False
            for m in mods:
                if (s + 1) % m == 0:
                    valid = True
                    break
            if valid:
                mat[state_idx[next_s]][state_idx[s]] += 1

    if n == 0:
        print(0)
        return

    mat_n = matrix_pow(mat, n, MOD)

    ans = 0
    start_state = 0
    start_idx = state_idx[start_state]
    for i in range(size):
        ans = (ans + mat_n[i][start_idx]) % MOD

    print(ans)

if __name__ == "__main__":
    solve()
